const lockEmployment = `-- name: LockEmployment :one
SELECT id, person_id, employment_number, relationship_type, business_unit_id, start_date, end_date, end_reason, contract_signed_at, revision, created_at, updated_at FROM staff.employments WHERE id = $1 FOR NO KEY UPDATE
`

// LockEmployment takes an employment's row after its person's, for the rest
// of the transaction. FOR NO KEY UPDATE, like the person's: a terms row's
// foreign key takes KEY SHARE on it, which this does not block.
func (q *Queries) LockEmployment(ctx context.Context, id int64) (StaffEmployment, error) {
	row := q.db.QueryRow(ctx, lockEmployment, id)
	var i StaffEmployment
	err := row.Scan(
		&i.ID,
		&i.PersonID,
		&i.EmploymentNumber,
		&i.RelationshipType,
		&i.BusinessUnitID,
		&i.StartDate,
		&i.EndDate,
		&i.EndReason,
		&i.ContractSignedAt,
		&i.Revision,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const moveTermsValidFrom = `-- name: MoveTermsValidFrom :exec
UPDATE staff.employment_terms SET valid_from = $1, revision = revision + 1, updated_at = $2::timestamptz
WHERE id = $3
`

type MoveTermsValidFromParams struct {
	ValidFrom pgtype.Date
	Now       time.Time
	ID        int64
}

// MoveTermsValidFrom moves the first terms row with its employment's start.
func (q *Queries) MoveTermsValidFrom(ctx context.Context, arg MoveTermsValidFromParams) error {
	_, err := q.db.Exec(ctx, moveTermsValidFrom, arg.ValidFrom, arg.Now, arg.ID)
	return err
}

const peopleSummaries = `-- name: PeopleSummaries :many
SELECT id, display_name, employee_number FROM staff.people WHERE id = ANY($1::bigint[])
`

type PeopleSummariesRow struct {
	ID             int64
	DisplayName    string
	EmployeeNumber string
}

// PeopleSummaries names people as the work group does.
func (q *Queries) PeopleSummaries(ctx context.Context, ids []int64) ([]PeopleSummariesRow, error) {
	rows, err := q.db.Query(ctx, peopleSummaries, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PeopleSummariesRow
	for rows.Next() {
		var i PeopleSummariesRow
		if err := rows.Scan(&i.ID, &i.DisplayName, &i.EmployeeNumber); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

